import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Rhinocs_%E5%8F%A4%E3%81%8F%E3%81%AA%E3%81%A3%E3%81%9F%E8%A9%B1%E9%A1%8C.html","title":"Rhinocs_古くなった話題","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.82,"words":546},"filePathRelative":"Rhinocs_古くなった話題.md"}`),a={name:`Rhinocs_古くなった話題.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="rhinocs-古くなった話題" tabindex="-1"><a class="header-anchor" href="#rhinocs-古くなった話題"><span>Rhinocs_古くなった話題</span></a></h1><p><a href="./Rhinocs.html">Rhinocs</a></p><p>考えているうちに変わった結果、残しておくと混乱がありそうなものを隔離する場所。 ここに持ってきて無くて古くなった話題もあるが。</p><h2 id="starlarcs" tabindex="-1"><a class="header-anchor" href="#starlarcs"><span>Starlarcs</span></a></h2><p>最初は<a href="./Starlark.html">Starlark</a>バックエンドにしようと思って<a href="./Starlarcs.html">Starlarcs</a>と呼んでいたが、今はRhinoバックエンドのRhinocsにする事にした。</p><h2 id="skkの実装を検討する" tabindex="-1"><a class="header-anchor" href="#skkの実装を検討する"><span>SKKの実装を検討する</span></a></h2><p>以前jmukがChromOS用に作ってたよなぁ、と思い調べると、そのあとhydrakecat氏がforkしている。</p><ul><li><a href="https://github.com/hkurokawa/chrome-skk/tree/main" target="_blank" rel="noopener noreferrer">hkurokawa/chrome-skk: An SKK implementation for ChromeOS IME API.</a></li></ul><p>まぁ自分の目的ではあまり違わなさそうだが。</p><p>これをそのまま移植するならパッケージとかextensionとかいろいろ考えないといけない事が多いので、まずはそういう難しい事はせずに一つのjsファイルに必要なのを切り貼りしていく感じにするか。</p><p>SKK-JISYOは開発中はSがいいな。</p><p><a href="https://skk-dev.github.io/dict/" target="_blank" rel="noopener noreferrer">SKK dictionary files gh-pages - dict</a></p><p>ここから落とせるか。</p><p>SKKの開発を始めるのに必要な事は以下か。</p><ol><li>skk.jsの場所を指定して保存するようにし、起動時に自動で読むようにする</li><li>skk.jsと同じフォルダにあるSKK-JISYO.Sをロードする</li></ol><p>この２つが終われば、あとはjs側の開発が始められる。</p><p>いや、一番最初は平仮名とカタカナでいいか。まずは平仮名の実装からはじめよう。</p><p>以前ちょっと調べた時にxyzzyの実装は割と簡単に実現できそうだった。</p><p><a href="https://github.com/loyaltouch/Skk-Mode/tree/master" target="_blank" rel="noopener noreferrer">loyaltouch/Skk-Mode: xyzzy-skk-mode</a></p><p>この辺を参考にしつつちょっとずつ進めたい。</p><h2 id="最初の目標" tabindex="-1"><a class="header-anchor" href="#最初の目標"><span>最初の目標</span></a></h2><p>考えないといけない事は無限にあって永遠に前に進めない気がするので、一番最初の目標を決めてそれに必要な事だけをやる感じにしたい。</p><p>やりたいのはこのWikiなどを書きたい。それに必要最低限のものから始めたい。</p><ul><li>SAFでのファイルの読み書き</li><li>日本語入力 <ul><li>SKK</li><li>ダイアログでEditText</li></ul></li><li>キーマップと基本的な入力</li><li>カット、コピー、ヤンク</li></ul><p>日本語入力は必須なので、最初から半角-全角の扱いはしたい。逆にこの枠組みに収まらない言語はやらない。</p><p>SKKはちゃんとやると結構いろいろな機能が必要になってしまうので、とりあえず複数windowが無くても出来るような範囲だけをやりたい。 ミニバッファ絡みの機能も最初はやらない。</p><p>その代わりEditTextで普通にタッチ入力する逃げ道は作っておきたい。</p><p>ウィンドウのsplitは無しでもまずはいけるか？ミニバッファとウィンドウのsplitがなければだいぶ話は楽そうだが。 switch-bufferは必要だろうが、最初の目標としては無しの状態でとりあえず動く所までを目指すか。</p><h3 id="最初の最初の目標はskkの実装を開始するまでの最低限" tabindex="-1"><a class="header-anchor" href="#最初の最初の目標はskkの実装を開始するまでの最低限"><span>最初の最初の目標はSKKの実装を開始するまでの最低限</span></a></h3><p>SKKを必要最低限に実装するのは結構大変ではある。 これが最初の目標というのは遠すぎる。</p><p>そして作り始めないと何が必要かは完全には分からないので、最初に作り始める所を最初の最初の目標とするか。</p><p>SKKを作り始めるのが最初の最初の目標とすると、必要なのはなんだろう？</p><ul><li>SAFでのファイルの読み書き</li><li>Rhinoのキーマップ経由のローマ字の入力</li><li>Rhinoによるjsのロード</li></ul><p>モードとかを最初に整備するのは避けたいので、単純にSAFでskk.jsをロードしてしまって良いとは思っている。 このくらいが動けばjsの作業を開始出来るか。</p><p>ここまでを最初の最初の目標とするか。</p><p>SKKを書き始めるのにとりあえず必要なのは以下か？</p><ul><li>Rhinoからのバッファの操作</li><li>Rhinoからの辞書のロード</li><li>Rhinoからのread-key的な処理</li></ul><p>この辺を揃え始めるのが最初の最初の目標かな。ドッグフードはまだまだだいぶ先だが。</p><h3 id="viewについての雑記-初期、やっぱり変える" tabindex="-1"><a class="header-anchor" href="#viewについての雑記-初期、やっぱり変える"><span>Viewについての雑記（初期、やっぱり変える）</span></a></h3><p>一行一TextViewで、RecyclerViewを使いたいが、厳しいかなぁ。 内部的には対応する行に合わせたグリフ情報を構成して、それを書く。 各TextViewは前に書いたグリフ情報はキャッシュし、、、ってそこまでやるならTextViewよりも自分で書く方がいいかなぁ。</p><p>View側と内部の両方を一気につくると永遠に完成しないのでViewは手抜きで始めたい気もするな。 そうすると一番単純にはスクロールとかは無視して、画面に表示している範囲の文字をdrawするだけの方が楽か。 まぁ最初はそこからか。</p><p>そう考えるなら<a href="./ZipSourceCodeReading.html">ZipSourceCodeReading</a>と同じ感じでいいか。 ZipSourceCodeReadingはスクロールがいまいちだったので、将来的には各行を表示するViewを作ってRecyclerViewに任せたい気もするが、 キーボード中心と割り切れば別にスクロールがいまいちでも我慢出来るかもしれない。 なんにせよ最初は単に配列を画面に表示するだけの方がいいな。</p><p>とりあえず、内部で画面に表示する文字の一覧を作る。これはグリフの配列とする。 Viewはそれを表示するだけで、スクロールとかは一切サポートしない。 こんな感じで始めるか。 グリフを作る所まではどうせ一緒なので、そこから先は真面目に書きたくなったら書けばいいだろう。</p>`,43)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};